timeexception.props">   <h2 class="title">属性</h2>   <dl>         <dt id="mongodb-driver-exception-runtimeexception.props.errorlabels"><var class="varname">errorLabels</var></dt>     <dd>      <span class="simpara">       Contains an array of error labels to go with an exception. For example,       error labels can be used to detect whether a transaction can be retried       safely if the <span class="literal">TransientTransactionError</span> label is       present. The existence of a specific error label should be tested for       with the       <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Exception\RuntimeException::hasErrorLabel()}</span>,       instead of interpreting this <span class="literal">errorLabels</span> property       manually.      </span>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 1.6.0</td>       <td>        <span class="simpara">         The         <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Exception\RuntimeException::hasErrorLabel()}</span>         method and         {@link MongoDB\Driver\Exception\RuntimeException::errorLabels}         property have been added.        </span>       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\Exception\RuntimeException::hasErrorLabel} — Returns whether an error label is associated with an exception</li></ul></div>
 * 
 * Thrown when the driver encounters a runtime error (e.g. internal error from » libmongoc).
 * @link https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php
 * @since 1.0.0
 */
class RuntimeException extends \RuntimeException implements Exception
{
    /**
     * @var bool
     * @since 1.6.0
     */
    protected $errorLabels;

    /**
     * Whether the given errorLabel is associated with this exception
     *
     * @since 1.6.0
     */
    final public function hasErrorLabel(string $label): bool {}
}
